declarations.type:
∀ {lam mu nu : YoungDiagram} {entry : Conjecture407.SkewCell lam nu → Nat} {contained : LE.le.{0} lam nu}
  {rowWeak :
    ∀ (a b : Conjecture407.SkewCell lam nu),
      Eq.{1} (↑a).1 (↑b).1 → LE.le.{0} (↑a).2 (↑b).2 → LE.le.{0} (entry a) (entry b)}
  {colStrict :
    ∀ (a b : Conjecture407.SkewCell lam nu),
      Eq.{1} (↑a).2 (↑b).2 → LT.lt.{0} (↑a).1 (↑b).1 → LT.lt.{0} (entry a) (entry b)}
  {content : ∀ (i : Nat), Eq.{1} (Conjecture407.entryCount entry i) (YoungDiagram.rowLen mu i)}
  {lattice :
    ∀ (b : Conjecture407.SkewCell lam nu) (i : Nat),
      LE.le.{0} (Conjecture407.prefixCount entry b (HAdd.hAdd.{0, 0, 0} i 1)) (Conjecture407.prefixCount entry b i)}
  {entry_1 : Conjecture407.SkewCell lam nu → Nat} {contained_1 : LE.le.{0} lam nu}
  {rowWeak_1 :
    ∀ (a b : Conjecture407.SkewCell lam nu),
      Eq.{1} (↑a).1 (↑b).1 → LE.le.{0} (↑a).2 (↑b).2 → LE.le.{0} (entry_1 a) (entry_1 b)}
  {colStrict_1 :
    ∀ (a b : Conjecture407.SkewCell lam nu),
      Eq.{1} (↑a).2 (↑b).2 → LT.lt.{0} (↑a).1 (↑b).1 → LT.lt.{0} (entry_1 a) (entry_1 b)}
  {content_1 : ∀ (i : Nat), Eq.{1} (Conjecture407.entryCount entry_1 i) (YoungDiagram.rowLen mu i)}
  {lattice_1 :
    ∀ (b : Conjecture407.SkewCell lam nu) (i : Nat),
      LE.le.{0} (Conjecture407.prefixCount entry_1 b (HAdd.hAdd.{0, 0, 0} i 1))
        (Conjecture407.prefixCount entry_1 b i)},
  Eq.{1}
      { entry := entry, contained := contained, rowWeak := rowWeak, colStrict := colStrict, content := content,
        lattice := lattice }
      { entry := entry_1, contained := contained_1, rowWeak := rowWeak_1, colStrict := colStrict_1,
        content := content_1, lattice := lattice_1 } →
    Eq.{1} entry entry_1
